// Character classification and escaping helpers.

// Approximation of Python's Unicode-aware \w (letter, decimal digit, or
// underscore) implemented with explicit code-point ranges so we do not
// depend on any external data tables.
export function isWordChar(ch) {
  if (ch === undefined || ch === '') return false;
  const cp = ch.codePointAt(0);
  if (cp < 128) {
    return (cp >= 48 && cp <= 57) || (cp >= 65 && cp <= 90) ||
           (cp >= 97 && cp <= 122) || cp === 95;
  }
  return (
    (cp >= 0xaa && cp <= 0xaa) || (cp >= 0xb5 && cp <= 0xb5) ||
    (cp >= 0xba && cp <= 0xba) ||
    (cp >= 0xc0 && cp <= 0xff && cp !== 0xd7 && cp !== 0xf7) || // Latin-1 letters
    (cp >= 0x0100 && cp <= 0x02af) ||   // Latin Extended
    (cp >= 0x0370 && cp <= 0x03ff) ||   // Greek
    (cp >= 0x0400 && cp <= 0x052f) ||   // Cyrillic
    (cp >= 0x0530 && cp <= 0x058f) ||   // Armenian
    (cp >= 0x0590 && cp <= 0x05ff) ||   // Hebrew
    (cp >= 0x0600 && cp <= 0x06ff) ||   // Arabic
    (cp >= 0x0900 && cp <= 0x097f) ||   // Devanagari
    (cp >= 0x3041 && cp <= 0x309f) ||   // Hiragana
    (cp >= 0x30a0 && cp <= 0x30ff) ||   // Katakana
    (cp >= 0x3400 && cp <= 0x4dbf) ||   // CJK Ext A
    (cp >= 0x4e00 && cp <= 0x9fff) ||   // CJK Unified
    (cp >= 0xa000 && cp <= 0xa4cf) ||
    (cp >= 0xac00 && cp <= 0xd7af) ||   // Hangul syllables
    (cp >= 0xf900 && cp <= 0xfaff) ||   // CJK compat
    (cp >= 0xff10 && cp <= 0xff19) ||   // fullwidth digits
    (cp >= 0xff21 && cp <= 0xff3a) ||   // fullwidth upper
    (cp >= 0xff41 && cp <= 0xff5a) ||   // fullwidth lower
    (cp >= 0x0660 && cp <= 0x0669) ||
    (cp >= 0x06f0 && cp <= 0x06f9) ||
    (cp >= 0x20000 && cp <= 0x2a6df)
  );
}

export function isDigit(ch) {
  return ch >= '0' && ch <= '9';
}

export function isASCIILetter(ch) {
  return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z');
}

export function isHexDigit(ch) {
  return isDigit(ch) || (ch >= 'a' && ch <= 'f') || (ch >= 'A' && ch <= 'F');
}

// Does the text starting at s[i] look like a character reference
// (&name; / &#123; / &#x1f;) that should be preserved verbatim?
export function entityMatchAt(s, i) {
  if (s[i] !== '&') return 0;
  let j = i + 1;
  if (s[j] === '#') {
    j++;
    if (s[j] === 'x' || s[j] === 'X') {
      j++;
      const start = j;
      while (j < s.length && isHexDigit(s[j])) j++;
      if (j > start && s[j] === ';') return j + 1 - i;
      return 0;
    }
    const start = j;
    while (j < s.length && isDigit(s[j])) j++;
    if (j > start && s[j] === ';') return j + 1 - i;
    return 0;
  }
  const start = j;
  while (j < s.length && isWordChar(s[j])) j++;
  if (j > start && s[j] === ';') return j + 1 - i;
  return 0;
}

// Escape text data: &, <, > (keeping valid entities), like ElementTree's
// HTML serializer used by Python-Markdown.
export function escapeCdata(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '&') {
      const m = entityMatchAt(text, i);
      if (m > 0) {
        out += text.slice(i, i + m);
        i += m - 1;
      } else {
        out += '&amp;';
      }
    } else if (ch === '<') {
      out += '&lt;';
    } else if (ch === '>') {
      out += '&gt;';
    } else {
      out += ch;
    }
  }
  return out;
}

// Escape an attribute value (double-quoted context).
export function escapeAttrib(text) {
  let out = '';
  for (let i = 0; i < text.length; i++) {
    const ch = text[i];
    if (ch === '&') {
      const m = entityMatchAt(text, i);
      if (m > 0) {
        out += text.slice(i, i + m);
        i += m - 1;
      } else {
        out += '&amp;';
      }
    } else if (ch === '<') {
      out += '&lt;';
    } else if (ch === '>') {
      out += '&gt;';
    } else if (ch === '"') {
      out += '&quot;';
    } else {
      out += ch;
    }
  }
  return out;
}

// Escape code-block content. Python-Markdown escapes code blocks with
// quote handling as well (html.escape style).
export function escapeCode(text) {
  let out = '';
  for (const ch of text) {
    if (ch === '&') out += '&amp;';
    else if (ch === '<') out += '&lt;';
    else if (ch === '>') out += '&gt;';
    else if (ch === '"') out += '&quot;';
    else if (ch === "'") out += '&#x27;';
    else out += ch;
  }
  return out;
}

// Python str.expandtabs(4)
export function expandTabs(s, tabSize) {
  let out = '';
  let col = 0;
  for (const ch of s) {
    if (ch === '\t') {
      const n = tabSize - (col % tabSize);
      out += ' '.repeat(n);
      col += n;
    } else {
      out += ch;
      if (ch === '\n') col = 0;
      else col++;
    }
  }
  return out;
}

