// HTML stash: stores raw HTML fragments behind unlikely placeholders so
// they survive inline/block processing untouched, mirroring
// Python-Markdown's util.HtmlStash.

export class HtmlStash {
  constructor() {
    this.html = [];
    this.counter = 0;
  }

  store(fragment) {
    const placeholder = 'klzzwxh:' + this.counter + '';
    this.html.push(fragment);
    this.counter++;
    return placeholder;
  }

  // Replace all placeholders in the serialized output with raw HTML.
  unescape(output) {
    for (let i = 0; i < this.html.length; i++) {
      const placeholder = 'klzzwxh:' + i + '';
      // A placeholder should appear at most once, but replace every
      // occurrence just in case.
      while (output.includes(placeholder)) {
        output = output.replace(placeholder, this.html[i]);
      }
    }
    return output;
  }
}

export const PLACEHOLDER_RE_CHARS = ['', ''];

