// Minimal element tree plus a serializer that reproduces the exact
// whitespace style of Python-Markdown's ElementTree-based HTML output.

import { escapeCdata, escapeAttrib } from './chars.mjs';

// Tags that get newline treatment when nested inside other elements.
const BLOCK_TAGS = new Set([
  'address', 'article', 'aside', 'blockquote', 'body', 'caption', 'center',
  'dd', 'details', 'dialog', 'dir', 'div', 'dl', 'dt', 'fieldset',
  'figcaption', 'figure', 'footer', 'form', 'h1', 'h2', 'h3', 'h4', 'h5',
  'h6', 'header', 'hr', 'li', 'main', 'menu', 'nav', 'ol', 'p', 'pre',
  'section', 'table', 'tbody', 'td', 'tfoot', 'th', 'thead', 'tr', 'ul',
]);

// Tags serialized without a closing tag (HTML format void elements).
const VOID_TAGS = new Set(['area', 'base', 'br', 'col', 'embed', 'hr', 'img',
  'input', 'link', 'meta', 'param', 'source', 'track', 'wbr']);

let rawCounter = 0;

export class El {
  constructor(tag) {
    this.tag = tag;          // string tag name, or null for a raw HTML node
    this.attrs = new Map();  // insertion does not matter; output is sorted
    this.text = null;        // text before first child
    this.children = [];
    this.tail = null;        // text after the element
    this.raw = null;         // for tag === null: raw html string
    this.id = rawCounter++;  // stable identity for bookkeeping
  }

  setAttr(name, value) {
    this.attrs.set(name, value);
  }

  append(child) {
    this.children.push(child);
    return child;
  }

  get lastChild() {
    return this.children.length ? this.children[this.children.length - 1] : null;
  }
}

export function rawNode(html) {
  const el = new El(null);
  el.raw = html;
  return el;
}

export function isBlockNode(el) {
  if (el.tag === null) return true; // raw html blocks stand alone
  return BLOCK_TAGS.has(el.tag);
}

function serializeAttrs(el) {
  if (el.attrs.size === 0) return '';
  const names = [...el.attrs.keys()].sort();
  let out = '';
  for (const name of names) {
    out += ' ' + name + '="' + escapeAttrib(String(el.attrs.get(name))) + '"';
  }
  return out;
}

function serializeInto(el, out) {
  if (el.tag === null) {
    out.push(el.raw);
    if (el.tail) out.push(escapeCdata(el.tail));
    return;
  }
  out.push('<' + el.tag + serializeAttrs(el));
  if (VOID_TAGS.has(el.tag) && el.children.length === 0 &&
      (el.text === null || el.text === '')) {
    out.push(' />');
  } else {
    out.push('>');
    const hasText = el.text !== null && el.text !== '';
    if (hasText) out.push(escapeCdata(el.text));
    for (let i = 0; i < el.children.length; i++) {
      const child = el.children[i];
      if (isBlockNode(child) && !(i === 0 && hasText)) {
        out.push('\n');
      }
      serializeInto(child, out);
    }
    const last = el.children.length ? el.children[el.children.length - 1] : null;
    if (last !== null && isBlockNode(last)) {
      out.push('\n');
    }
    out.push('</' + el.tag + '>');
  }
  if (el.tail) out.push(escapeCdata(el.tail));
}

// Serialize a list of top-level nodes (the document root's children).
export function serializeDocument(children) {
  const out = [];
  for (let i = 0; i < children.length; i++) {
    const child = children[i];
    if (i > 0 && isBlockNode(child)) {
      out.push('\n');
    }
    serializeInto(child, out);
  }
  return out.join('');
}

